code.source:
#include <iostream>
using namespace std;

int main() {
    int grid[2][3] = {{1, 2, 3}, {4, 5, 6}};
    cout << grid[0][2] << endl;
    cout << grid[1][0] << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int grid[2][3] = {{1, 2, 3}, {4, 5, 6}};
    for (int r = 0; r < 2; r++) {
        int sum = 0;
        for (int c = 0; c < 3; c++) {
            sum += grid[r][c];
        }
        cout << "Row " << r << ": " << sum << endl;
    }
    return 0;
}

